package com.mahweb.mahyarnfc.omnishare.ble;
import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.ByteBuffer; import java.nio.charset.StandardCharsets; import java.util.Arrays;
public final class HmacEphemeralTokenProvider implements EphemeralTokenProvider { private final byte[]secret; public HmacEphemeralTokenProvider(byte[]s){if(s==null||s.length<16)throw new IllegalArgumentException("secret");secret=Arrays.copyOf(s,s.length);} public byte[] currentToken(long now){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));m.update("mahyar-ble-token-v1".getBytes(StandardCharsets.UTF_8));m.update(ByteBuffer.allocate(8).putLong(now/300000L).array());return Arrays.copyOf(m.doFinal(),8);}catch(Exception e){throw new IllegalStateException(e);}} }
